mapper.insert:
/* ApprovalLineMapper.insertApprovalStep */
INSERT INTO TB_USER_ATTD_REQ_APPROVAL (
      REQ_ID
    , APPROVAL_STEP
    , CMPNY_CD
    , APPROVER_USER_CD
    , APPROVAL_STATUS
    , APPROVAL_COMMENT
    , APPROVAL_DATE
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      #{reqId}
    , #{approvalStep}
    , #{cmpnyCd}
    , #{approverUserCd}
    , #{approvalStatus}
    , #{approvalComment}
    , NULL
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.update:
/* ApprovalLineMapper.updateStepStatus */
UPDATE TB_USER_ATTD_REQ_APPROVAL
   SET APPROVAL_STATUS  = #{approvalStatus}
     , APPROVAL_COMMENT = #{approvalComment}
     , APPROVAL_DATE    = NOW()
     , UPDATE_NO        = #{processUserCd}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND REQ_ID        = #{reqId}
   AND APPROVAL_STEP = #{approvalStep}

/* ApprovalLineMapper.updateStepStatusGuarded */
UPDATE TB_USER_ATTD_REQ_APPROVAL
   SET APPROVAL_STATUS  = #{approvalStatus}
     , APPROVAL_COMMENT = #{approvalComment}
     , APPROVAL_DATE    = NOW()
     , UPDATE_NO        = #{processUserCd}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD        = #{cmpnyCd}
   AND REQ_ID          = #{reqId}
   AND APPROVAL_STEP   = #{approvalStep}
   AND APPROVAL_STATUS = #{fromStatus}

mapper.delete:
/* ApprovalLineMapper.deleteApprovalLineByReqId */

DELETE FROM TB_USER_ATTD_REQ_APPROVAL
 WHERE CMPNY_CD = #{cmpnyCd}
   AND REQ_ID   = #{reqId}

mapper.select:
/* ApprovalLineMapper.selectApprovalStep */
SELECT
      A.REQ_ID            AS reqId
    , A.APPROVAL_STEP     AS approvalStep
    , A.CMPNY_CD          AS cmpnyCd
    , A.APPROVER_USER_CD  AS approverUserCd
    , A.APPROVAL_STATUS   AS approvalStatus
    , A.APPROVAL_COMMENT  AS approvalComment
  FROM TB_USER_ATTD_REQ_APPROVAL A
 WHERE A.CMPNY_CD      = #{cmpnyCd}
   AND A.REQ_ID        = #{reqId}
   AND A.APPROVAL_STEP = #{approvalStep}
 LIMIT 1

/* ApprovalLineMapper.selectFirstWaitingStep */
SELECT MIN(A.APPROVAL_STEP)
  FROM TB_USER_ATTD_REQ_APPROVAL A
 WHERE A.CMPNY_CD        = #{cmpnyCd}
   AND A.REQ_ID          = #{reqId}
   AND A.APPROVAL_STATUS = '00'

/* ApprovalLineMapper.selectDefaultApproverOfNode */
SELECT IFNULL(N.MAIN_ADMIN_CD, N.SUB_ADMIN_CD)
  FROM TB_SITE_NODE N
 WHERE N.CMPNY_CD = #{cmpnyCd}
   AND N.SITE_CD  = #{siteCd}
   AND N.NODE_CD  = #{nodeCd}
 LIMIT 1
